args.new:
if doc_ids is not None:
    # When both doc_ids and cond are provided, remove only documents
    # whose ID is in doc_ids *and* that satisfy the condition.
    # If cond is None, behave as before (remove by IDs only).
    requested_ids = list(doc_ids)
    removed_ids: list[int] = []

    def updater(table: dict):
        # Determine which IDs to remove based on existence and condition
        if cond is not None:
            # Evaluate condition on each document
            _cond = cast(QueryLike, cond)
            ids_to_remove = [
                doc_id for doc_id in requested_ids
                if doc_id in table and _cond(table[doc_id])
            ]
        else:
            ids_to_remove = [doc_id for doc_id in requested_ids if doc_id in table]
        removed_ids.extend(ids_to_remove)
        for doc_id in ids_to_remove:
            del table[doc_id]

    # Perform the remove operation
    self._update_table(updater)

    return removed_ids
